// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

/**
 * {@code GROUP_CONCAT(?o; separator=",")} and {@code GROUP_CONCAT(?o; separator="|")} differ only in
 * {@link GroupConcat#getSeparator()}; they must never compare equal.
 */
class GroupConcatEqualityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void separatorParticipatesInEquality() {
		GroupConcat comma = concat(",");
		GroupConcat pipe = concat("|");

		assertNotEquals(comma, pipe, "different separators must not be equal");
		assertNotEquals(pipe, comma);
		assertNotEquals(comma.hashCode(), pipe.hashCode(), "hash codes must separate the separators");
		assertNotEquals(comma, concat(null), "an explicit separator differs from the default one");
		assertNotEquals(concat(null), comma);
	}

	@Test
	void sameSeparatorStaysEqual() {
		assertEquals(concat(","), concat(","));
		assertEquals(concat(",").hashCode(), concat(",").hashCode());
		assertEquals(concat(null), concat(null));
		assertEquals(concat(null).hashCode(), concat(null).hashCode());
	}

	@Test
	void distinctStillParticipatesInEquality() {
		GroupConcat distinct = new GroupConcat(Var.of("o"), true);
		distinct.setSeparator(new ValueConstant(VF.createLiteral(",")));

		assertNotEquals(concat(","), distinct);
	}

	private static GroupConcat concat(String separator) {
		GroupConcat concat = new GroupConcat(Var.of("o"));
		if (separator != null) {
			concat.setSeparator(new ValueConstant(VF.createLiteral(separator)));
		}
		return concat;
	}
}
